public static void main(String[] args) {
    // m/s
    double velocidadInicial = 10;
    // m/s²
    double aceleracion = 2;
    // s
    double tiempo = 5;
    double velocidadFinal = velocidadInicial + aceleracion * tiempo;
    System.out.println("Velocidad final: " + velocidadFinal + " m/s");
}
